using System;
class HinhChuNhat {
    int dai, rong;
    public HinhChuNhat(int d, int r) {
        dai = d;
        rong = r;
    }
    public int DienTich() => dai * rong;
}
class Program {
    static void Main() {
        var h = new HinhChuNhat(5, 3);
        Console.WriteLine(h.DienTich());
    }
}
